orView()+aiView()+apiLabView()+sqlLabView()+pythonLabView()+webLabView()+agentLabView()+gitLabView()+reviewLabView()+capstoneView()+'<div class="buttons">'+a('next-mission',esc(tr(progress().mission===MISSIONS.length-1?'quiz':'nextMission')),'lime')+'</div><p class="help">'+esc(tr('draftSaved'))+'</p>';
